var DATA = {"scope": "Shared product catalog across 3 orgs", "rules": "partner => allow read catalog|internal => deny all|admin => allow all", "enforcement": "Federation gateway", "exceptions": "Break-glass for incidents with audit", "tests": "partner reads catalog|partner reads internal notes|admin writes catalog"};
console.log("Federation policy scope: " + DATA.scope);
console.log("Enforcement point: " + DATA.enforcement);
var rules = DATA.rules.split("|").map(function (s) { return s.trim(); });
var requests = DATA.tests.split("|").map(function (s) { return s.trim(); });
requests.forEach(function (req) {
  var decision = "DENY", matched = "default-deny";
  rules.forEach(function (rule) {
    var parts = rule.split("=>").map(function (s) { return s.trim(); });
    if (parts.length === 2 && req.toLowerCase().indexOf(parts[0].toLowerCase()) >= 0) {
      decision = parts[1].toUpperCase(); matched = rule;
    }
  });
  console.log("  request [" + req + "] => " + decision + " (rule: " + matched + ")");
});
console.log("Exceptions: " + DATA.exceptions);
console.log("RESULT: " + requests.length + " federated requests evaluated against " + rules.length + " rules.");

